185	static uint64_t read_reg64(struct qemu_plugin_register *h)
186	{
187	    if (!h) return 0;
188	    g_autoptr(GByteArray) buf = g_byte_array_new();
189	    int sz = qemu_plugin_read_register(h, buf);
190	    if (sz <= 0) return 0;
191	    uint64_t v = 0;
192	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
193	    return v;
194	}
