211	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
212	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
213	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
214	// collide even under aggressive PID reuse (B13). The tmp lives in the
215	// same directory as `path` so the rename is intra-filesystem.
216	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
217	{
218	    char tmp[PATH_MAX];
219	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
220	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
221	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
222	        return -1;
223	    }
224	    int fd = g_mkstemp(tmp);
225	    if (fd < 0) {
226	        perror("hybrid_handoff: g_mkstemp");
227	        return -1;
228	    }
229	    // g_mkstemp creates the file 0600; no further chmod needed.
230	    ssize_t want = (ssize_t) sizeof(*s);
231	    ssize_t got = write(fd, s, sizeof(*s));
232	    if (got != want) {
233	        perror("hybrid_handoff: write");
234	        close(fd);
235	        unlink(tmp);
236	        return -1;
237	    }
238	    fsync(fd);
239	    close(fd);
240	    if (rename(tmp, path) != 0) {
241	        perror("hybrid_handoff: rename");
242	        unlink(tmp);
243	        return -1;
244	    }
245	    return 0;
246	}
