248	// Drain CPU state to outfile_path. pc is computed by the caller (from a
249	// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
250	// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
251	// minstret in the state file (used by drain_at_exit mode to record a
252	// plugin-counted retired-insn total). Does NOT call exit -- caller
253	// decides exit(200) (normal trigger) vs _exit(200) (inside atexit chain).
254	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
255	                                uint64_t minstret_override)
256	{
257	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
258	    resolve_handles(v);
259	    struct hybrid_state_v1 s = {0};
260	    s.magic   = HYBRID_STATE_MAGIC;
261	    s.version = HYBRID_STATE_VERSION;
262	    s.flags   = HYBRID_FLAG_RV64;
263	    s.hart_id = vcpu_idx;
264	    s.priv    = 3;
265	    s.pc      = pc;
266	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
267	
268	    // Floating-point: only set FP flag if at least one handle was bound,
269	    // i.e. QEMU advertised the FPU feature (D extension).
270	    int has_fp = 0;
271	    for (int i = 0; i < 32; i++) {
272	        s.fpr[i] = read_reg64(v->fpr[i]);
273	        if (v->fpr[i]) has_fp = 1;
274	    }
275	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
276	
277	    s.mstatus  = read_reg64(v->mstatus);
278	    s.mepc     = read_reg64(v->mepc);
279	    s.mtvec    = read_reg64(v->mtvec);
280	    s.mcause   = read_reg64(v->mcause);
281	    s.mtval    = read_reg64(v->mtval);
282	    s.mscratch = read_reg64(v->mscratch);
283	    s.medeleg  = read_reg64(v->medeleg);
284	    s.mideleg  = read_reg64(v->mideleg);
285	    s.mip      = read_reg64(v->mip);
286	    s.mie      = read_reg64(v->mie);
287	    s.mcycle   = read_reg64(v->mcycle);
288	    s.minstret = minstret_override ? minstret_override
289	                                   : read_reg64(v->minstret);
290	    s.satp     = read_reg64(v->satp);
